"""Edge-case tests for the secondary-y-axis subsystem (GH #52) — generated by
bug-hunter agent.

Targets: ``ferrum.structural.SecondaryY`` + ``chart._desugar_secondary_y``
(the S4 field guard, ``_column_names_for_validation``),
``LayerChart._build_merged`` / ``_y_independent`` routing,
``composition._lower_any`` / ``_contains_independent_y_layer`` (nesting
conflict detection), and ``_spec_build._build_layers_list``'s
``independent_y`` wire flag.

Every test names the code path it exercises. Failing tests are kept with a
``# BUG:`` marker — they prove the bug exists.
"""

from __future__ import annotations

import json
import re

import polars as pl
import pytest

import ferrum as fm
from ferrum.composition import HConcatChart, LayerChart, VConcatChart
from ferrum.structural import SecondaryY
from tests._svg_extents import y_axis_extents


# ---------------------------------------------------------------------------
# Helpers (mirrors tests/test_secondary_y_axis.py conventions)
# ---------------------------------------------------------------------------


def _svg_body(svg: str) -> str:
    """Strip the embedded base64 font block so token checks don't false-positive."""
    idx = svg.find("</defs>")
    return svg[idx:] if idx != -1 else svg


def _rotated_titles(svg: str) -> list[str]:
    """Axis-title texts (the only rotated <text> nodes these charts emit)."""
    body = _svg_body(svg)
    return [
        text.strip()
        for attrs, text in re.findall(r"<text\s+([^>]*)>([^<]*)</text>", body)
        if "rotate(" in attrs
    ]


def _assert_no_bad_tokens(svg: str) -> None:
    """The SVG contract: no NaN / Infinity coordinates anywhere in the body."""
    body = _svg_body(svg)
    assert "NaN" not in body, "NaN leaked into SVG geometry"
    assert "Infinity" not in body, "Infinity leaked into SVG geometry"
    assert not re.search(r"\binf\b", body), "'inf' token leaked into SVG geometry"


def _df():
    return pl.DataFrame(
        {
            "x": [1, 2, 3, 4],
            "y": [1.0, 2.0, 3.0, 4.0],
            "z": [100.0, 200.0, 150.0, 300.0],
        }
    )


def _empty_df():
    return pl.DataFrame(
        {
            "x": pl.Series("x", [], dtype=pl.Float64),
            "y": pl.Series("y", [], dtype=pl.Float64),
            "z": pl.Series("z", [], dtype=pl.Float64),
        }
    )


def _dual_layerchart(df):
    bars = fm.Chart(df).mark_bar().encode(x="x", y="y")
    line = fm.Chart(df).mark_line().encode(x="x", y="z")
    return LayerChart(bars, line, resolve={"y": "independent"})


# ---------------------------------------------------------------------------
# Null / NaN — Rust resolves the secondary slot's y-scale from the layer's
# batch; nulls must not poison the domain (Layer::independent_y slot resolve).
# ---------------------------------------------------------------------------


def test_null_in_secondary_column_renders_without_nan():
    df = pl.DataFrame({"x": [1, 2, 3], "y": [1.0, 2.0, 3.0], "z": [1.0, None, 3.0]})
    svg = (fm.Chart(df).mark_bar().encode(x="x", y="y") + SecondaryY("z")).to_svg()
    _assert_no_bad_tokens(svg)
    assert "z" in _rotated_titles(svg)


def test_all_null_secondary_column_renders_without_nan():
    """Degenerate slot domain: the independent layer's y column is 100% null.

    Targets the per-layer y-scale resolve for a flagged layer whose batch has
    no finite values — must not emit NaN coordinates or panic.
    """
    df = pl.DataFrame(
        {
            "x": [1, 2, 3],
            "y": [1.0, 2.0, 3.0],
            "z": pl.Series("z", [None, None, None], dtype=pl.Float64),
        }
    )
    svg = (fm.Chart(df).mark_bar().encode(x="x", y="y") + SecondaryY("z")).to_svg()
    _assert_no_bad_tokens(svg)


# ---------------------------------------------------------------------------
# Empty inputs — the merged flat path (independent y) vs. the composite
# overlay path (shared y) have different empty-data handling.
# ---------------------------------------------------------------------------


def test_zero_row_base_plus_secondary_y_renders_placeholder():
    """Zero-row polars frame still exposes its schema, so the S4 field guard
    passes and the render must fall through to the empty-dataset placeholder
    (Chart.to_svg empty path), not divide by len or index [0]."""
    chart = fm.Chart(_empty_df()).mark_bar().encode(x="x", y="y") + SecondaryY("z")
    svg = chart.to_svg()
    assert svg.startswith("<svg")
    _assert_no_bad_tokens(svg)


def test_all_empty_independent_y_layerchart_renders_valid_svg():
    """resolve={"y": "independent"} routes through _build_merged (the flat
    path), which renders the plain-Chart empty placeholder instead of the
    composite tree's typed all-empty ValueError. Pin: valid SVG, no NaN.
    (The shared route raising while this renders is the documented flat-path
    exception; what must NOT happen is a panic or NaN viewBox.)"""
    a = fm.Chart(_empty_df()).mark_bar().encode(x="x", y="y")
    b = fm.Chart(_empty_df()).mark_line().encode(x="x", y="z")
    svg = LayerChart(a, b, resolve={"y": "independent"}).to_svg()
    assert svg.startswith("<svg")
    _assert_no_bad_tokens(svg)


def test_one_empty_layer_under_independent_y_renders():
    """One member empty, one full: __add__ diagonal-concats a 0-row frame and
    the flagged layer's slot resolves from zero rows of its own column."""
    full = fm.Chart(_df()).mark_bar().encode(x="x", y="y")
    empty_line = fm.Chart(_empty_df()).mark_line().encode(x="x", y="z")
    svg = LayerChart(full, empty_line, resolve={"y": "independent"}).to_svg()
    assert svg.startswith("<svg")
    _assert_no_bad_tokens(svg)


# ---------------------------------------------------------------------------
# Single-row / degenerate domain — per-slot scale resolve with a collapsed
# domain must not produce 0/0 in the y position math.
# ---------------------------------------------------------------------------


def test_single_row_dual_axis_renders_without_nan():
    df = pl.DataFrame({"x": [1], "y": [2.0], "z": [500.0]})
    svg = (fm.Chart(df).mark_bar().encode(x="x", y="y") + SecondaryY("z")).to_svg()
    _assert_no_bad_tokens(svg)
    assert "z" in _rotated_titles(svg)


def test_constant_secondary_column_degenerate_domain():
    """All secondary values identical → the slot's domain collapses to a
    point. The scale resolve must widen it (or anchor it), not divide by a
    zero span."""
    df = pl.DataFrame({"x": [1, 2, 3], "y": [1.0, 2.0, 3.0], "z": [42.0, 42.0, 42.0]})
    svg = (fm.Chart(df).mark_bar().encode(x="x", y="y") + SecondaryY("z")).to_svg()
    _assert_no_bad_tokens(svg)
    assert "z" in _rotated_titles(svg)


# ---------------------------------------------------------------------------
# Extreme values
# ---------------------------------------------------------------------------


def test_inf_in_secondary_column_no_nan_or_inf_tokens():
    """f64::INFINITY in the independent slot's column must not leak NaN /
    Infinity into SVG coordinates (per-slot domain resolve)."""
    df = pl.DataFrame({"x": [1, 2, 3], "y": [1.0, 2.0, 3.0], "z": [1.0, float("inf"), 3.0]})
    svg = (fm.Chart(df).mark_bar().encode(x="x", y="y") + SecondaryY("z")).to_svg()
    _assert_no_bad_tokens(svg)


def test_extreme_magnitude_secondary_values_no_nan():
    """1e300-magnitude values in the secondary slot: the pixel math must not
    overflow into NaN and the tick formatter must not emit 'inf'."""
    df = pl.DataFrame({"x": [1, 2, 3], "y": [1.0, 2.0, 3.0], "z": [1e300, 5e299, 8e299]})
    svg = (fm.Chart(df).mark_bar().encode(x="x", y="y") + SecondaryY("z")).to_svg()
    _assert_no_bad_tokens(svg)


# ---------------------------------------------------------------------------
# Per-slot scale config — SecondaryY(scale=) flows onto the appended layer's
# Y channel (chart._desugar_secondary_y y_kwargs) and must configure ONLY
# that slot.
# ---------------------------------------------------------------------------


def test_log_scale_on_secondary_slot_only():
    svg = (
        fm.Chart(_df()).mark_bar().encode(x="x", y="y") + SecondaryY("z", scale=fm.LogScale())
    ).to_svg()
    _assert_no_bad_tokens(svg)
    titles = _rotated_titles(svg)
    assert "y" in titles and "z" in titles


def test_symlog_scale_on_secondary_slot_with_negatives():
    df = pl.DataFrame(
        {"x": [1, 2, 3, 4], "y": [1.0, 2.0, 3.0, 4.0], "z": [-100.0, 5.0, -3.0, 200.0]}
    )
    svg = (
        fm.Chart(df).mark_bar().encode(x="x", y="y") + SecondaryY("z", scale=fm.SymlogScale())
    ).to_svg()
    _assert_no_bad_tokens(svg)
    assert "z" in _rotated_titles(svg)


def test_log_scale_secondary_with_zero_in_domain_no_nan():
    """log(0) = -inf: a zero in the secondary column under a log slot must
    not put NaN/-Infinity into the emitted geometry."""
    df = pl.DataFrame({"x": [1, 2, 3], "y": [1.0, 2.0, 3.0], "z": [0.0, 10.0, 100.0]})
    svg = (
        fm.Chart(df).mark_bar().encode(x="x", y="y") + SecondaryY("z", scale=fm.LogScale())
    ).to_svg()
    _assert_no_bad_tokens(svg)


def test_secondary_axis_title_override_renders():
    """SecondaryY(axis=fm.Axis(title=...)) rides y_kwargs['axis'] onto the
    appended layer's Y channel — the right axis must show the custom title."""
    svg = (
        fm.Chart(_df()).mark_bar().encode(x="x", y="y")
        + SecondaryY("z", axis=fm.Axis(title="Right Axis"))
    ).to_svg()
    assert "Right Axis" in svg


# ---------------------------------------------------------------------------
# Type boundaries — the S4 field guard (_column_names_for_validation,
# e521955b) across input kinds and non-string field values.
# ---------------------------------------------------------------------------


def test_field_guard_int_field_raises_with_legible_message():
    with pytest.raises(ValueError, match=r"SecondaryY: field 123 is not a column"):
        fm.Chart(_df()).mark_point().encode(x="x", y="y") + SecondaryY(123)


def test_field_guard_tuple_field_raises():
    with pytest.raises(ValueError, match=r"not a column"):
        fm.Chart(_df()).mark_point().encode(x="x", y="y") + SecondaryY(("a", "b"))


def test_field_guard_none_field_raises():
    with pytest.raises(ValueError, match=r"not a column"):
        fm.Chart(_df()).mark_point().encode(x="x", y="y") + SecondaryY(None)


def test_field_guard_empty_string_field_raises():
    with pytest.raises(ValueError, match=r"not a column"):
        fm.Chart(_df()).mark_point().encode(x="x", y="y") + SecondaryY("")


def test_field_guard_pandas_string_columns_raises_at_add_time():
    """pandas frames hit the generic `.columns` fallback branch of
    _column_names_for_validation (all-str column names → guard active)."""
    import pandas as pd

    pdf = pd.DataFrame({"x": [1, 2, 3], "y": [1.0, 2.0, 3.0]})
    base = fm.Chart(pdf).mark_point().encode(x="x", y="y")
    with pytest.raises(ValueError, match=r"'nope'.*not a column"):
        base + SecondaryY("nope")


def test_field_guard_pandas_int_columns_skips_check():
    """pandas frames with non-string column names fail the all-str predicate
    → guard returns None → check skipped (documented: render-time errors
    remain). The + must succeed and append the flagged layer."""
    import pandas as pd

    pdf = pd.DataFrame({0: [1, 2, 3], 1: [1.0, 2.0, 3.0]})
    base = fm.Chart(pdf).mark_point().encode(x="0", y="1")
    chart = base + SecondaryY("nope")  # guard skipped; must not raise here
    assert chart._layers[-1].independent_y is True


def test_field_guard_polars_lazyframe_raises_at_add_time():
    """The pl.LazyFrame branch of _column_names_for_validation
    (collect_schema().names()) must catch a bogus field at + time."""
    base = fm.Chart(_df().lazy()).mark_point().encode(x="x", y="y")
    with pytest.raises(ValueError, match=r"'nope'.*not a column"):
        base + SecondaryY("nope")


def test_field_guard_pyarrow_recordbatch_raises_at_add_time():
    """The pa.RecordBatch branch (schema.names) — existing tests only cover
    pa.Table."""
    import pyarrow as pa

    batch = pa.RecordBatch.from_pydict({"x": [1, 2, 3], "y": [1.0, 2.0, 3.0]})
    base = fm.Chart(batch).mark_point().encode(x="x", y="y")
    with pytest.raises(ValueError, match=r"'nope'.*not a column"):
        base + SecondaryY("nope")


def test_dict_of_arrays_guard_skipped_valid_field_renders_end_to_end():
    """dict-of-arrays has no cheap name listing → guard skipped (returns
    None); a VALID field must still render through the flat dual-axis path."""
    data = {"x": [1, 2, 3], "y": [1.0, 2.0, 3.0], "z": [10.0, 20.0, 30.0]}
    chart = fm.Chart(data).mark_point().encode(x="x", y="y") + SecondaryY("z")
    svg = chart.to_svg()
    _assert_no_bad_tokens(svg)
    assert "z" in _rotated_titles(svg)


def test_dict_of_arrays_bogus_field_errors_at_render_not_silently():
    """Guard skipped for dict data, but the bogus column must still surface a
    legible error at render time — not a silent no-mark render."""
    data = {"x": [1, 2, 3], "y": [1.0, 2.0, 3.0]}
    chart = fm.Chart(data).mark_point().encode(x="x", y="y") + SecondaryY("nope")
    with pytest.raises(Exception, match=r"nope"):
        chart.to_svg()


def test_categorical_x_shared_across_slots():
    """String x → band scale shared by the bar layer AND the flagged line
    layer (the overlay contract keeps one x coordinate space across slots)."""
    df = pl.DataFrame({"cat": ["a", "b", "c"], "y": [1.0, 2.0, 3.0], "z": [10.0, 20.0, 30.0]})
    svg = (fm.Chart(df).mark_bar().encode(x="cat", y="y") + SecondaryY("z")).to_svg()
    _assert_no_bad_tokens(svg)
    titles = _rotated_titles(svg)
    assert "y" in titles and "z" in titles


# ---------------------------------------------------------------------------
# Composition corners
# ---------------------------------------------------------------------------


# _contains_independent_y_layer only detects LayerChart instances, not plain
# Charts whose _layers carry independent_y=True flags — so the GH #52 spec §4
# nesting conflict is raised for one spelling of a dual-axis chart and
# silently skipped for the other.
def test_hconcat_explicit_shared_y_over_secondary_y_chart_raises():  # BUG: renders silently; z slot stays independent under an explicit parent resolve={"y": "shared"}
    """The SAME dual-axis chart spelled as `LayerChart(..., resolve=
    {"y": "independent"})` raises under a parent resolve={"y": "shared"}
    (see test_parent_explicit_shared_y_over_independent_y_layer_raises in
    tests/test_secondary_y_axis.py). Spelling it `chart + SecondaryY(...)`
    must hit the same conflict — the flagged layers equally cannot
    participate in cross-panel y sharing."""
    df = _df()
    dual_flat = fm.Chart(df).mark_bar().encode(x="x", y="y") + SecondaryY("z")
    other = fm.Chart(df).mark_point().encode(x="x", y="y")
    composite = HConcatChart([other, dual_flat], resolve={"y": "shared"})
    with pytest.raises(ValueError, match=r"(?s)shared.*independent"):
        composite.to_svg()


# LayerChart's shared-y overlay route (_composite_tree) force-sets y "shared"
# without checking whether a member's _layers carry independent_y=True flags,
# so the explicit shared request silently coexists with a dual axis.
def test_layerchart_explicit_shared_y_over_flagged_member_raises():  # BUG: renders the dual axis anyway; explicit resolve={"y": "shared"} silently ignored for the flagged layer
    df = _df()
    dual_flat = fm.Chart(df).mark_bar().encode(x="x", y="y") + SecondaryY("z")
    other = fm.Chart(df).mark_point().encode(x="x", y="y")
    layered = LayerChart(dual_flat, other, resolve={"y": "shared"})
    with pytest.raises(ValueError, match=r"(?s)shared.*independent"):
        layered.to_svg()


def test_vconcat_shared_y_conflict_raises_like_hconcat():
    """The nesting conflict error (composition._lower_any) must fire for
    VConcatChart too, naming the class the caller typed."""
    df = _df()
    other = fm.Chart(df).mark_point().encode(x="x", y="y")
    composite = VConcatChart([other, _dual_layerchart(df)], resolve={"y": "shared"})
    with pytest.raises(ValueError, match=r"VConcatChart:.*'y': 'shared'.*independent-y"):
        composite.to_svg()


def test_deeply_nested_dual_axis_conflict_detected():
    """_contains_independent_y_layer recurses through .charts: a dual-axis
    LayerChart two levels down (VConcat → HConcat → LayerChart) must still
    trip the top-level explicit shared-y."""
    df = _df()
    other = fm.Chart(df).mark_point().encode(x="x", y="y")
    inner = HConcatChart([other, _dual_layerchart(df)])
    composite = VConcatChart([inner], resolve={"y": "shared"})
    with pytest.raises(ValueError, match=r"'y': 'shared'.*independent-y"):
        composite.to_svg()


def test_secondary_y_chart_as_nonfirst_layerchart_member_hits_multi_y_guard():
    """Double-desugar corner: a `chart + SecondaryY(...)` result used as a
    NON-first member under resolve={"y": "independent"} contributes 2
    y-bearing layers → the _build_merged multi-y-layer guard must raise, on
    BOTH render entries."""
    df = _df()
    dual_flat = fm.Chart(df).mark_bar().encode(x="x", y="y") + SecondaryY("z")
    primary = fm.Chart(df).mark_point().encode(x="x", y="y")
    layered = LayerChart(primary, dual_flat, resolve={"y": "independent"})
    with pytest.raises(ValueError, match=r"position 1.*2 y-bearing layers"):
        layered.to_svg()
    with pytest.raises(ValueError, match=r"position 1.*2 y-bearing layers"):
        layered._render_interactive()


def test_secondary_y_chart_as_first_member_stacks_third_axis():
    """The primary member is exempt from the multi-y guard: a SecondaryY
    chart as FIRST member plus another independent member renders three
    axes (y left, z right, z2 right — slot order preserved)."""
    df = pl.DataFrame(
        {
            "x": [1, 2, 3, 4],
            "y": [1.0, 2.0, 3.0, 4.0],
            "z": [100.0, 200.0, 150.0, 300.0],
            "z2": [-5.0, -2.0, -8.0, -1.0],
        }
    )
    dual_flat = fm.Chart(df).mark_bar().encode(x="x", y="y") + SecondaryY("z")
    third = fm.Chart(df).mark_point().encode(x="x", y="z2")
    svg = LayerChart(dual_flat, third, resolve={"y": "independent"}).to_svg()
    titles = _rotated_titles(svg)
    assert sorted(titles) == ["y", "z", "z2"], f"expected 3 axis titles, got {titles}"


def test_share_scale_y_independent_sugar_matches_constructor():
    """LayerChart.share_scale(y='independent') stores Resolve(scale={...});
    the docstring promises the Resolve form and the flat-dict form lower to
    byte-identical SVG."""
    df = _df()
    bars = fm.Chart(df).mark_bar().encode(x="x", y="y")
    line = fm.Chart(df).mark_line().encode(x="x", y="z")
    via_sugar = LayerChart(bars, line).share_scale(y="independent").to_svg()
    via_ctor = LayerChart(bars, line, resolve={"y": "independent"}).to_svg()
    assert via_sugar == via_ctor
    assert len(y_axis_extents(via_sugar)) == 2


def test_resolve_object_form_y_independent_renders_dual_axis():
    """fm.Resolve(scale={'y': 'independent'}) must route through
    _y_independent → _build_merged exactly like the flat-dict form (every
    existing test uses the flat dict)."""
    df = _df()
    bars = fm.Chart(df).mark_bar().encode(x="x", y="y")
    line = fm.Chart(df).mark_line().encode(x="x", y="z")
    svg = LayerChart(bars, line, resolve=fm.Resolve(scale={"y": "independent"})).to_svg()
    titles = _rotated_titles(svg)
    assert "y" in titles and "z" in titles
    assert len(y_axis_extents(svg)) == 2


def test_facet_with_secondary_y_renders_right_axis_per_panel():
    """Faceting a SecondaryY-desugared chart: each partition panel must keep
    the flagged layer's right axis (facet partitioner × per-layer slots)."""
    df = pl.DataFrame(
        {
            "x": [1, 2, 3, 4] * 2,
            "y": [1.0, 2.0, 3.0, 4.0] * 2,
            "z": [10.0, 20.0, 30.0, 40.0] * 2,
            "g": ["a"] * 4 + ["b"] * 4,
        }
    )
    chart = (fm.Chart(df).mark_bar().encode(x="x", y="y") + SecondaryY("z")).facet(col="g")
    svg = chart.to_svg()
    _assert_no_bad_tokens(svg)
    titles = _rotated_titles(svg)
    assert titles.count("z") == 2, f"expected a right z-axis on each of 2 panels, got {titles}"


# Chart.__add__'s column-collision suffix (chart.py ~line 1623) becomes
# user-visible under independent y because the flagged slot titles its axis
# from the layer's own (renamed) field.
def test_heterogeneous_data_secondary_axis_title_has_no_rhs_sentinel():  # BUG: internal "__rhs_<hex>" rename rendered as the secondary axis title
    """Two members with DIFFERENT data but overlapping column names:
    __add__ renames the RHS columns to '{col}__rhs_{hex}' before the
    diagonal concat. Under resolve={"y": "independent"} the renamed field
    becomes the right axis's title. Internal sentinels must never reach
    the rendered SVG."""
    df_a = _df()
    df_b = pl.DataFrame({"x": [1, 2, 3, 4], "y": [10.0, 20.0, 30.0, 40.0]})
    bars = fm.Chart(df_a).mark_bar().encode(x="x", y="y")
    line = fm.Chart(df_b).mark_line().encode(x="x", y="y")
    svg = LayerChart(bars, line, resolve={"y": "independent"}).to_svg()
    assert "__rhs_" not in svg, (
        f"internal RHS-rename sentinel leaked into the SVG (axis titles: {_rotated_titles(svg)})"
    )


def test_base_without_y_encoding_plus_secondary_renders():
    """Slot contract says layer 0 is always the primary/left axis — but here
    layer 0 (mark_tick, x only) has NO y encoding at all. The flagged z layer
    must still get its axis without a phantom primary axis or a panic."""
    df = pl.DataFrame({"x": [1, 2, 3], "z": [10.0, 20.0, 30.0]})
    chart = fm.Chart(df).mark_tick().encode(x="x") + SecondaryY("z")
    svg = chart.to_svg()
    _assert_no_bad_tokens(svg)
    assert "z" in _rotated_titles(svg)


# ---------------------------------------------------------------------------
# Transforms on the secondary member — __add__'s named-transform routing
# (data_source) composed with the independent_y flag.
# ---------------------------------------------------------------------------


def test_smooth_transform_on_secondary_member_renders_dual_axis():
    df = pl.DataFrame(
        {
            "x": [1.0, 2.0, 3.0, 4.0],
            "y": [1.0, 2.0, 3.0, 4.0],
            "z": [100.0, 200.0, 150.0, 300.0],
        }
    )
    primary = fm.Chart(df).mark_bar().encode(x="x", y="y")
    smooth = fm.Chart(df).mark_line().encode(x="x", y="z").transform(fm.Smooth("x", "z"))
    svg = LayerChart(primary, smooth, resolve={"y": "independent"}).to_svg()
    _assert_no_bad_tokens(svg)
    titles = _rotated_titles(svg)
    assert "y" in titles and "z" in titles


def test_aggregate_shorthand_on_secondary_member_renders():
    """encode(y="mean(z)") on the secondary member: the _PendingAggregate
    resolves per-layer and the flagged slot must scale off the aggregated
    output column."""
    df = pl.DataFrame(
        {"x": [1, 1, 2, 2], "y": [1.0, 2.0, 3.0, 4.0], "z": [10.0, 20.0, 30.0, 40.0]}
    )
    primary = fm.Chart(df).mark_bar().encode(x="x", y="y")
    agg = fm.Chart(df).mark_line().encode(x="x", y="mean(z)")
    svg = LayerChart(primary, agg, resolve={"y": "independent"}).to_svg()
    _assert_no_bad_tokens(svg)
    assert len(y_axis_extents(svg)) == 2


# ---------------------------------------------------------------------------
# Spec round-trips — _build_layers_list's independent_y wire flag.
# ---------------------------------------------------------------------------


def test_independent_y_survives_chartspec_json_roundtrip():
    from ferrum._core import ChartSpec

    chart = fm.Chart(_df()).mark_bar().encode(x="x", y="y") + SecondaryY("z")
    spec = chart.to_spec()
    j = json.loads(spec.to_json())
    assert j["layers"][1].get("independent_y") is True
    # Base layer must NOT carry the flag (absent, for pre-#52 byte-stability).
    assert "independent_y" not in j["layers"][0] or j["layers"][0]["independent_y"] is False
    # Round-trip through Rust serde must preserve it.
    rt = json.loads(ChartSpec.from_json(spec.to_json()).to_json())
    assert rt["layers"][1].get("independent_y") is True


# ---------------------------------------------------------------------------
# Interactive contract — the SecondaryY-desugared chart is a plain Chart, so
# its scene render is the flat single-panel entry (_render_scene).
# ---------------------------------------------------------------------------


def test_scene_render_of_secondary_y_desugared_chart_is_one_panel():
    from ferrum._scene import _render_scene

    chart = fm.Chart(_df()).mark_bar().encode(x="x", y="y") + SecondaryY("z")
    scene_json, packed = _render_scene(chart)
    scene = json.loads(scene_json)
    assert len(scene["panels"]) == 1
    assert isinstance(packed, (bytes, bytearray))
    assert "__rhs_" not in scene_json
